import{_ as a,o,c as i,a2 as r}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md"}'),s={name:"materias/Redes/documentacion/II-V/Lectura_Catedra_Evaluacion_1.md"};function n(t,e,c,l,d,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-redes-trayecto-ii" tabindex="-1">Materia: Redes (Trayecto II) <a class="header-anchor" href="#materia-redes-trayecto-ii" aria-label="Permalink to &quot;Materia: Redes (Trayecto II)&quot;">​</a></h2><h3 id="eje-tematico-planeacion-diseno-lan-y-estandares-ieee" tabindex="-1">Eje Temático: Planeación, Diseño LAN y Estándares IEEE <a class="header-anchor" href="#eje-tematico-planeacion-diseno-lan-y-estandares-ieee" aria-label="Permalink to &quot;Eje Temático: Planeación, Diseño LAN y Estándares IEEE&quot;">​</a></h3><hr><h2 id="🧭-introduccion-arquitectura-antes-de-la-implementacion" tabindex="-1">🧭 Introducción: Arquitectura antes de la Implementación <a class="header-anchor" href="#🧭-introduccion-arquitectura-antes-de-la-implementacion" aria-label="Permalink to &quot;🧭 Introducción: Arquitectura antes de la Implementación&quot;">​</a></h2><p>Si te contratan para construir un edificio de 20 pisos, no empiezas a apilar ladrillos al azar. Primero contratas a un arquitecto para que trace los planos y asegure que los cimientos soporten el peso.</p><p>En ingeniería de redes, el proceso es idéntico. Antes de comprar un solo metro de cable o configurar una dirección IP, el ingeniero debe realizar un proceso riguroso de <strong>Planeación y Diseño LAN</strong>. Una red mal diseñada hoy, será una red que colapsará mañana cuando la empresa contrate a 50 nuevos empleados.</p><hr><h2 id="🏛️-capitulo-i-el-proceso-de-planeacion-de-red" tabindex="-1">🏛️ CAPÍTULO I: El Proceso de Planeación de Red <a class="header-anchor" href="#🏛️-capitulo-i-el-proceso-de-planeacion-de-red" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Proceso de Planeación de Red&quot;">​</a></h2><p>El diseño de una red local (LAN) se divide en fases estructuradas:</p><ol><li><strong>Recolección de Requisitos:</strong> ¿Para qué se usará la red? Una red para un cibercafé que descarga videojuegos requiere un diseño diferente a la red de un banco que procesa millones de transacciones pequeñas pero hiper-seguras.</li><li><strong>Selección de Topología y Medio:</strong> Decidir si usar Estrella o Malla. Decidir si la conexión vertical entre pisos (Backbone) será de Fibra Óptica (por la velocidad y para evitar interferencia de los ascensores) y la conexión horizontal a las computadoras será de Cobre UTP Cat 6.</li><li><strong>Plano de Direccionamiento Lógico:</strong> Calcular matemáticamente cuántas direcciones IP se necesitarán en el presente y en un futuro a 5 años (Escalabilidad).</li><li><strong>Seguridad Física:</strong> Determinar la ubicación del &quot;Cuarto de Telecomunicaciones&quot; (Site / MDF), asegurando ventilación adecuada, UPS (baterías de respaldo) y control de acceso biométrico.</li></ol><hr><h2 id="🧩-capitulo-ii-el-modelo-de-diseno-jerarquico-de-3-capas-cisco" tabindex="-1">🧩 CAPÍTULO II: El Modelo de Diseño Jerárquico de 3 Capas (Cisco) <a class="header-anchor" href="#🧩-capitulo-ii-el-modelo-de-diseno-jerarquico-de-3-capas-cisco" aria-label="Permalink to &quot;🧩 CAPÍTULO II: El Modelo de Diseño Jerárquico de 3 Capas (Cisco)&quot;">​</a></h2><p>Para redes medianas y grandes, la industria no conecta todos los switches entre sí como una telaraña. Se utiliza el modelo jerárquico de Cisco, que divide la red física en tres capas lógicas:</p><ol><li><strong>Capa de Acceso (Access Layer):</strong> Son los switches baratos que están en los pasillos o paredes. Su único trabajo es darle conexión directa a las computadoras de los empleados, impresoras y teléfonos IP.</li><li><strong>Capa de Distribución (Distribution Layer):</strong> Son switches más potentes e inteligentes ubicados en el cuarto de servidores de cada piso. Reciben los cables de todos los switches de Acceso de ese piso y aplican políticas de seguridad (Ej: &quot;El departamento de ventas no puede ver las impresoras de recursos humanos&quot;).</li><li><strong>Capa Núcleo (Core Layer):</strong> Es el &quot;corazón&quot; de la red. Son equipos extremadamente costosos y ultra-rápidos de fibra óptica. Su única misión es conmutar tráfico a la velocidad de la luz entre los diferentes pisos o edificios sin aplicar reglas pesadas.</li></ol><hr><h2 id="🏗️-capitulo-iii-los-estandares-ieee-802" tabindex="-1">🏗️ CAPÍTULO III: Los Estándares IEEE 802 <a class="header-anchor" href="#🏗️-capitulo-iii-los-estandares-ieee-802" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Los Estándares IEEE 802&quot;">​</a></h2><p>Si compras una tarjeta Wi-Fi en China y un Router en Alemania, funcionan juntos mágicamente. Esto es gracias al <strong>IEEE (Instituto de Ingenieros Eléctricos y Electrónicos)</strong>, un comité mundial que dictamina las reglas exactas de cómo deben fabricarse las tecnologías.</p><p>El comité IEEE tiene un grupo de trabajo específico para Redes Locales y Metropolitanas llamado <strong>IEEE 802</strong>.</p><h3 id="subcomites-criticos-que-debes-conocer" tabindex="-1">Subcomités Críticos que debes conocer: <a class="header-anchor" href="#subcomites-criticos-que-debes-conocer" aria-label="Permalink to &quot;Subcomités Críticos que debes conocer:&quot;">​</a></h3><ul><li><strong>IEEE 802.3 (Ethernet):</strong> Es el estándar que define todo sobre el cable de cobre y la fibra en redes LAN. Dicta desde el grosor del hilo hasta cómo deben lidiar con las colisiones.</li><li><strong>IEEE 802.11 (Wi-Fi):</strong> Define las comunicaciones LAN inalámbricas (Wireless LAN / WLAN). Ha evolucionado a lo largo de los años para soportar más velocidad y frecuencias: <ul><li><code>802.11g</code> (Velocidad vieja, 54 Mbps).</li><li><code>802.11n</code> (Wi-Fi 4 - Usaba múltiples antenas MIMO).</li><li><code>802.11ac</code> (Wi-Fi 5 - Banda de 5GHz, hiper rápido).</li><li><code>802.11ax</code> (Wi-Fi 6 - El estándar moderno de ultra alta densidad).</li></ul></li><li><strong>IEEE 802.15 (Bluetooth/PAN):</strong> Estándar para Redes de Área Personal inalámbricas de corto alcance.</li></ul><hr><h2 id="💻-laboratorio-teorico-el-simulador-packet-tracer" tabindex="-1">💻 Laboratorio Teórico: El Simulador (Packet Tracer) <a class="header-anchor" href="#💻-laboratorio-teorico-el-simulador-packet-tracer" aria-label="Permalink to &quot;💻 Laboratorio Teórico: El Simulador (Packet Tracer)&quot;">​</a></h2><p>En lugar de gastar miles de dólares comprando equipos reales para practicar, la industria utiliza simuladores de red. El más famoso es <strong>Cisco Packet Tracer</strong>.</p><p><strong>Flujo de trabajo en el simulador:</strong></p><ol><li>Arrastras un <em>Switch 2960</em> al espacio de trabajo.</li><li>Arrastras dos <em>PCs genéricas</em>.</li><li>Usas la herramienta de cableado (Rayo naranja) para seleccionar &quot;Cable Directo de Cobre&quot; (Straight-Through).</li><li>Conectas el puerto <em>FastEthernet0/1</em> del Switch al puerto <em>FastEthernet0</em> de la PC1.</li><li>Inmediatamente verás los &quot;leds&quot; de enlace en color ámbar mientras negocian, y luego en verde cuando hay conexión física exitosa (Capa 1 y 2 del modelo OSI operativas).</li></ol><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Planeación LAN:</strong> Fase arquitectónica deductiva donde se establecen los requerimientos topológicos, físicos y lógicos de una infraestructura de red local para garantizar rendimiento, seguridad y escalabilidad operativa.</li><li><strong>Modelo Jerárquico de 3 Capas:</strong> Arquitectura de diseño de red estandarizada que particiona la topología física en Capa de Acceso (conectividad final), Capa de Distribución (agregación y políticas) y Capa Núcleo (conmutación troncal de ultra alta velocidad).</li><li><strong>IEEE (Institute of Electrical and Electronics Engineers):</strong> Asociación técnico-profesional mundial responsable de la estandarización y desarrollo de normas tecnológicas en áreas de ingeniería eléctrica y ciencias de la computación.</li><li><strong>IEEE 802.3 (Ethernet):</strong> Conjunto normativo de especificaciones técnicas que define la estandarización de las capas Física (PHY) y de Control de Acceso al Medio (MAC) para arquitecturas de red alámbricas LAN.</li><li><strong>IEEE 802.11 (Wi-Fi):</strong> Estándar de la industria que especifica el conjunto de protocolos de control de acceso al medio y capa física para la implementación de redes locales inalámbricas (WLAN) sobre bandas de radiofrecuencia (típicamente 2.4GHz y 5GHz).</li><li><strong>Packet Tracer:</strong> Herramienta de software propietaria de simulación visual de redes diseñada por Cisco Systems, empleada masivamente en entornos académicos para la emulación topológica, configuración de hardware virtualizado y análisis de tráfico.</li></ul>',29)])])}const E=a(s,[["render",n]]);export{m as __pageData,E as default};
